const flowCurrency=/^(?:(?:h|h2o|atp|adp|amp|pi|ppi|nad|nadh|nadp|nadph|coa)_[cep]|cpd(?:00001|00002|00003|00004|00005|00006|00008|00009|00018|00067)_\w+)$/;
function flowIndex(short,pool){const s=D.species.find(s=>s.short===short),nodes=new Map(),edges=[],out=new Map(),incoming=new Map();const add=(id,data)=>nodes.set(id,{data:{id,...data}});const edge=(a,b,extra={})=>{let e={data:{id:'fedge_'+edges.length,source:a,target:b,...extra}};edges.push(e);if(!out.has(a))out.set(a,[]);out.get(a).push(e);if(!incoming.has(b))incoming.set(b,[]);incoming.get(b).push(e)};const rootMids=new Set(s.reactions.filter(r=>r.pool===pool).flatMap(r=>Object.keys(r.stoich)));const root='feed';add(root,{label:(pools.find(x=>x[0]===pool)?.[1]||pool)+'\n培地 '+(D.medium?.[pool]??'未指定')+' mmol/L',kind:'feed',pool});Object.entries(s.metabolites).forEach(([m,o])=>add('m_'+m,{label:m,kind:'fm',mid:m,name:o.name}));let rxnMap=new Map();s.reactions.forEach(r=>{rxnMap.set(r.id,r);if(r.exchange){if(r.pool===pool&&r.uptake){let id='ex_'+r.id;add(id,{label:r.id,kind:'fr',reaction:r.id,direction:'取込'});edge(root,id);Object.keys(r.stoich).forEach(m=>edge(id,'m_'+m))}return}for(const sign of [1,-1]){if(sign===1?r.bounds[1]<=0:r.bounds[0]>=0)continue;let id='r_'+r.id+'_'+sign;add(id,{label:r.id+(sign<0?' (逆)':''),kind:'fr',reaction:r.id,direction:sign});Object.entries(r.stoich).forEach(([m,c])=>{if(flowCurrency.test(m)&&!rootMids.has(m)&&m.replace(/_[cep]\d*$/,'')!==pool.replace(/_e\d*$/,''))return;edge(c*sign<0?'m_'+m:id,c*sign<0?id:'m_'+m,{coefficient:c*sign})})}});
let dist=new Map([[root,0]]),parent=new Map(),queue=[root];for(let i=0;i<queue.length;i++){let id=queue[i];for(let e of out.get(id)||[]){let t=e.data.target;if(!dist.has(t)){dist.set(t,dist.get(id)+1);parent.set(t,{id,edge:e.data.id});queue.push(t)}}}let layers=new Map();queue.forEach(id=>{let d=dist.get(id);if(!layers.has(d))layers.set(d,[]);layers.get(d).push(id)});layers.forEach((ids,d)=>{ids.forEach((id,j)=>{let rank=j===0?0:Math.ceil(j/2)*(j%2?1:-1);nodes.get(id).position={x:d*220,y:rank*100}})});return {s,pool,nodes,edges,out,incoming,dist,parent,root,queue,layers,rxnMap,selected:root,loaded:new Set(),path:new Set([root]),pathEdges:new Set(),depth:Math.max(...dist.values())}}
function flowChoose(id){let st=flowState;st.selected=id;st.path=new Set();st.pathEdges=new Set();let cur=id;while(cur){st.path.add(cur);let p=st.parent.get(cur);if(p)st.pathEdges.add(p.edge);cur=p?.id}flowRender();let n=st.nodes.get(id)?.data;if(!n)return;let html='<h3>'+esc(n.label)+'</h3>';if(n.reaction){let r=st.rxnMap.get(n.reaction);html+='<p>'+esc(r.name)+'</p><div class="equation">'+esc(r.equation)+'</div><p>上下限 '+r.bounds.join(' ～ ')+'<br>GPR '+esc(r.gpr||'なし')+'</p><button id="flowEscher">この反応の周辺をEscherで開く</button>';}else if(n.mid)html+='<p>'+esc(n.name)+'</p>';let branches=st.out.get(id)||[];html+='<p>次の分岐 '+branches.length+' 件</p>'+branches.map(e=>'<button class="flowBranch" data-id="'+esc(e.data.target)+'" style="width:100%;margin:3px 0;text-align:left">'+esc(st.nodes.get(e.data.target).data.label)+'</button>').join('');$('flowDetails').innerHTML=html;$('flowDetails').querySelectorAll('.flowBranch').forEach(b=>b.onclick=()=>flowNavigate(b.dataset.id));if($('flowEscher'))$('flowEscher').onclick=()=>{let r=st.rxnMap.get(n.reaction),mids=new Set(Object.keys(r.stoich).filter(m=>!flowCurrency.test(m))),rs=st.s.reactions.filter(x=>x.id===r.id||Object.keys(x.stoich).some(m=>mids.has(m)));flowMode=false;escherOpen(st.s.short,rs,r.id+' 周辺 / '+rs.length+'反応');const back=document.createElement('button');back.textContent='培地からの追跡へ戻る';back.onclick=()=>openFlow(st.s.short,st.pool);$('context').prepend(back)}}
