function flowRender(){if(!flowMode||!flowState||!mapCy)return;let membrane=550*mapCy.zoom()+mapCy.pan().x,tint=flowState.s.short==='OR16'?'#f0f8f5':flowState.s.short==='NS21'?'#f1f5fc':'#fcf6ef';cyHost.style.background='linear-gradient(to right,#fbfcfa '+Math.max(0,membrane)+'px,'+tint+' '+Math.max(0,membrane)+'px)';let st=flowState,ext=mapCy.extent(),margin=260,visible=new Set();st.queue.forEach(id=>{let p=st.nodes.get(id).position;if(p.x>ext.x1-margin&&p.x<ext.x2+margin&&p.y>ext.y1-margin&&p.y<ext.y2+margin)visible.add(id)});st.path.forEach(id=>visible.add(id));let ghost=new Set();visible.forEach(id=>{for(let e of [...(st.out.get(id)||[]),...(st.incoming.get(id)||[])]){let t=e.data.source===id?e.data.target:e.data.source;if(st.dist.has(t)&&!visible.has(t))ghost.add(t)}});let wanted=new Set([...visible,...ghost]),els=[];wanted.forEach(id=>{if(!mapCy.getElementById(id).length)els.push(st.nodes.get(id))});mapCy.batch(()=>{mapCy.add(els);let es=[];st.edges.forEach(e=>{if(wanted.has(e.data.source)&&wanted.has(e.data.target)&&!mapCy.getElementById(e.data.id).length)es.push(e)});mapCy.add(es);mapCy.nodes().filter(n=>!wanted.has(n.id())).remove();mapCy.elements().removeClass('mainPath selectedFlow peripheral');mapCy.elements().addClass('peripheral');st.path.forEach(id=>mapCy.getElementById(id).removeClass('peripheral').addClass('mainPath'));st.pathEdges.forEach(id=>mapCy.getElementById(id).removeClass('peripheral').addClass('mainPath'));mapCy.getElementById(st.selected).addClass('selectedFlow')});$('atlasStatus').textContent='培地起点 · 画面周辺 '+mapCy.nodes().length+'ノード / 到達可能 '+st.dist.size+'ノード';}
