/* Persistent backbone and expandable product branches. */
function branchEnsure(st,r,sign){const id=r.exchange?'ex_'+r.id:'r_'+r.id+'_'+sign;if(!st.nodes.has(id))st.nodes.set(id,{data:{id,label:r.id+(sign===-1?' (逆)':''),kind:'fr',reaction:r.id,direction:sign}});return id}
function branchConnect(st,a,b){let e=st.edges.find(e=>e.data.source===a&&e.data.target===b);if(!e){e={data:{id:'branchEdge_'+st.edges.length,source:a,target:b}};st.edges.push(e);if(!st.out.has(a))st.out.set(a,[]);st.out.get(a).push(e);if(!st.incoming.has(b))st.incoming.set(b,[]);st.incoming.get(b).push(e)}return e.data.id}
function branchConsumers(st,mid){let found=[];for(let r of st.s.reactions){if(r.exchange||!(mid in r.stoich))continue;for(let sign of [1,-1])if((sign===1?r.bounds[1]>0:r.bounds[0]<0)&&r.stoich[mid]*sign<0)found.push({r,sign})}return found}
function branchInit(st){if(st.keep)return;st.keep=new Set();st.keepEdges=new Set();st.expanded=new Set();st.visibleProducts=new Set();st.renderNodes=new Set();st.layoutDone=new Set();}
function branchPinPath(st,id){let cur=id;while(cur){st.keep.add(cur);let p=st.parent.get(cur);if(p){st.keepEdges.add(p.edge);cur=p.id}else break}}
function branchProducts(st,rid){let data=st.nodes.get(rid).data,r=st.rxnMap.get(data.reaction);if(!r)return;let sign=data.direction===-1?-1:1;if(r.exchange)return;let p=st.nodes.get(rid).position||{x:660,y:0};let prods=Object.entries(r.stoich).filter(([,c])=>c*sign>0);prods.forEach(([m],j)=>{let id='m_'+m;branchConnect(st,rid,id);st.visibleProducts.add(id);if(!st.keep.has(id)&&!st.layoutDone.has(id)){st.nodes.get(id).position={x:p.x+220,y:p.y+(j+1)*80};st.layoutDone.add(id)}})}
flowChoose=function(id){let st=flowState;branchInit(st);if(!st.nodes.has(id))return;let d=st.nodes.get(id).data;st.selected=id;if(!st.keep.size||(!st.visibleProducts.has(id)&&!st.renderNodes.has(id)))branchPinPath(st,id);else st.keep.add(id);if(d.mid&&!chooserInitializing){st.expanded.add(id);let p=st.nodes.get(id).position;let consumers=branchConsumers(st,d.mid);consumers.forEach(({r,sign},j)=>{let rid=branchEnsure(st,r,sign);branchConnect(st,id,rid);if(!st.keep.has(rid)&&!st.layoutDone.has(rid)){st.nodes.get(rid).position={x:p.x+220,y:p.y+(j-Math.floor(consumers.length/2))*130};st.layoutDone.add(rid)};branchProducts(st,rid)})}if(d.reaction)branchProducts(st,id);for(let n of st.keep)if(st.nodes.get(n)?.data.reaction)branchProducts(st,n);flowRender();let html='<h3>'+esc(d.label)+'</h3><p>元の培地からの主経路を保持しています。</p>';if(d.mid){html+='<p>'+esc(d.name)+'<br>この成分を消費する '+branchConsumers(st,d.mid).length+' 反応を展開</p>'}if(d.reaction){let r=st.rxnMap.get(d.reaction);html+='<p>'+esc(r.name)+'</p><div class="equation">'+esc(r.equation)+'</div><p>上下限 '+r.bounds.join(' ～ ')+'</p><p>生成物はすべて表示。主生成物／副生成物の区別はモデルから断定せず、選んだ経路と他の生成物として描画します。</p>'}let children=(st.out.get(id)||[]).filter(e=>st.nodes.has(e.data.target));html+=children.map(e=>'<button class="branchNext" data-id="'+esc(e.data.target)+'" style="display:block;width:100%;margin:4px 0">'+esc(st.nodes.get(e.data.target).data.label)+'</button>').join('');$('flowDetails').innerHTML=html;$('flowDetails').querySelectorAll('.branchNext').forEach(b=>b.onclick=()=>{let edge=branchConnect(st,id,b.dataset.id);st.keepEdges.add(edge);st.keep.add(id);flowNavigate(b.dataset.id)})};
flowRender=function(){if(!flowMode||!flowState||!mapCy)return;let st=flowState;branchInit(st);const wanted=new Set(st.keep),activeRxns=new Set([...st.keep].filter(id=>st.nodes.get(id)?.data.reaction));for(let mid of st.expanded){wanted.add(mid);for(let e of st.out.get(mid)||[]){let d=st.nodes.get(e.data.target)?.data;if(d?.reaction){wanted.add(e.data.target);activeRxns.add(e.data.target)}}}for(let rid of activeRxns){wanted.add(rid);branchProducts(st,rid);for(let e of st.out.get(rid)||[])if(st.nodes.get(e.data.target)?.data.mid)wanted.add(e.data.target)}st.renderNodes=wanted;let elements=[];for(let id of wanted){let n=st.nodes.get(id);if(!n.position)n.position={x:0,y:0};if(!mapCy.getElementById(id).length)elements.push(n)}let badges=[];for(let id of wanted){let n=st.nodes.get(id);if(false){let count=0;if(count){let bid='fold_'+id;badges.push(bid);if(!mapCy.getElementById(bid).length)elements.push({data:{id:bid,label:'＋ '+count+'反応',kind:'fold',target:id},position:{x:n.position.x,y:n.position.y+48}})}}}mapCy.batch(()=>{mapCy.add(elements);mapCy.nodes().filter(n=>!wanted.has(n.id())&&!badges.includes(n.id())).remove();let additions=[];for(let e of st.edges)if(wanted.has(e.data.source)&&wanted.has(e.data.target)&&!mapCy.getElementById(e.data.id).length)additions.push(e);mapCy.add(additions);mapCy.elements().removeClass('mainPath selectedFlow peripheral');mapCy.elements().addClass('peripheral');st.keep.forEach(id=>mapCy.getElementById(id).removeClass('peripheral').addClass('mainPath'));st.keepEdges.forEach(id=>mapCy.getElementById(id).removeClass('peripheral').addClass('mainPath'));mapCy.nodes('[kind="fm"]').removeClass('peripheral');mapCy.getElementById(st.selected).addClass('selectedFlow')});$('atlasStatus').textContent='主経路を保持 · 展開中の成分 '+st.expanded.size+' · '+activeRxns.size+'反応';};
const persistentOpen=openFlow;openFlow=function(...args){persistentOpen(...args);let st=flowState;branchInit(st);appendFlowStyle(mapCy,[{selector:'node[kind="fold"]',style:{shape:'roundrectangle',width:75,height:22,'font-size':11,'text-valign':'center','text-margin-y':0,'background-color':'#e0e7ea','border-width':0}},{selector:'node[kind="fm"]',style:{opacity:1}},{selector:'edge.peripheral',style:{opacity:.22}},{selector:'node[kind="fr"].peripheral',style:{width:4,height:4,'font-size':11,opacity:.45}}]).update();mapCy.off('tap');mapCy.on('tap','node',e=>{let d=e.target.data();if(d.kind==='fold')flowNavigate(d.target);else flowChoose(d.id)});let note=document.createElement('p');note.textContent='入口は選択培地を取込可能な交換反応だけ。生成物の「＋反応」を選ぶと、その成分の消費反応を展開します。濃い主経路は保持されます。実際の取込量は未計算です。';$('context').prepend(note);flowRender();};
