const consumerUncached=branchConsumers;branchConsumers=function(st,mid){if(!st.consumerCache)st.consumerCache=new Map();if(!st.consumerCache.has(mid))st.consumerCache.set(mid,consumerUncached(st,mid));return st.consumerCache.get(mid)};
const branchChooseBase=flowChoose;flowChoose=function(id){let st=flowState,prev=st.selected;if(st.keep&&(st.out.get(prev)||[]).some(e=>e.data.target===id)){st.keepEdges.add(branchConnect(st,prev,id));st.keep.add(prev)}branchChooseBase(id);let trail=$('flowTrail');if(!trail){trail=document.createElement('p');trail.id='flowTrail';$('flowDetails').prepend(trail)}trail.textContent='保持中の主経路: '+[...st.keep].filter(id=>st.nodes.get(id)?.data.reaction).sort((a,b)=>(st.dist.get(a)??999)-(st.dist.get(b)??999)).map(id=>st.nodes.get(id).data.label).join(' → ');};
const branchDetailChoose=flowChoose;flowChoose=function(id){branchDetailChoose(id);let st=flowState,d=st.nodes.get(id)?.data;if(!d?.reaction)return;let b=document.createElement('button');b.textContent='周辺反応をEscherで確認';b.onclick=()=>{let r=st.rxnMap.get(d.reaction),mids=new Set(Object.keys(r.stoich).filter(m=>!flowCurrency.test(m))),rs=st.s.reactions.filter(r=>Object.keys(r.stoich).some(m=>mids.has(m)));flowMode=false;escherOpen(st.s.short,rs,r.id+' 周辺');let back=document.createElement('button');back.textContent='保持した経路へ戻る';back.onclick=()=>{openFlow(st.s.short,st.pool);flowState=st;mapCy.elements().remove();flowMode=true;flowNavigate(id)};$('context').prepend(back)};$('flowDetails').append(b)};
// Reflow retained route before centering; never center on an obsolete branch position.
function flowCenterRoute(exchangeOnly=false){if(!flowMode||!flowState)return;let st=flowState,route=mapCy.nodes().filter(n=>st.keep.has(n.id()));if(!route.length)return;if(exchangeOnly){let ex=route.filter(n=>n.id().startsWith('ex_'));if(ex.length){mapCy.zoom(.85);mapCy.center(ex);return}}mapCy.fit(route,80);if(mapCy.zoom()>1)mapCy.zoom(1);mapCy.center(route);}
