// Ranking uses one species-wide solution, not per-reaction feasibility maxima.
async function loadCommonRanking(short){const st=flowState,medium=st.mediumOverride,key=short+':'+JSON.stringify(medium||null);st.commonRankings=st.commonRankings||new Map();if(!st.commonRankings.has(key))st.commonRankings.set(key,(async()=>{try{const response=await fetch('http://localhost:8769/ranking?species='+encodeURIComponent(short)+(medium?'&medium='+encodeURIComponent(JSON.stringify(medium)):''),{signal:AbortSignal.timeout(120000)});if(!response.ok)throw new Error('HTTP');return await response.json()}catch{return {status:'unknown',message:'共通pFBAを取得できませんでした。'}}})());return st.commonRankings.get(key)}

// Hidden canvas updates must not compete with the reaction search page.
const visibleCanvasTabBase=tab;
tab=function(which){flowCanvasSuspended=which!=='map';hideCompoundTools();if(flowCanvasSuspended&&mapCy&&!mapCy.destroyed())mapCy.stop();visibleCanvasTabBase(which);$('flowTab').classList.toggle('active',which==='map'&&flowMode);if(!flowCanvasSuspended&&flowMode){refineEscherBranches();applyFbaColors();}};

flowTab.onclick=()=>{if(flowMode&&flowState&&mapCy&&!mapCy.destroyed()){tab('map');$('mapTab').classList.remove('active');flowTab.classList.add('active');mapCy.resize();}else openFlow();};

// Selection belongs to the reaction, including both sides of its main line.
function applyReactionSelection(){if(!flowMode||!flowState||!mapCy)return;const st=flowState,cy=mapCy;const pathwayReactions=new Set([...(st.majorShown?.values()||[])].flatMap(info=>info.pathway.reactions));cy.elements().removeClass('selectedReaction');cy.nodes('[kind="fr"]').forEach(rn=>{const selected=!rn.hasClass('userOmitted')&&(st.keep.has(rn.id())||pathwayReactions.has(rn.data('reaction')));if(!selected)return;rn.addClass('selectedReaction').removeClass('peripheral');rn.connectedEdges().forEach(e=>{if(e.hasClass('userOmitted'))return;e.addClass('selectedReaction').removeClass('peripheral')})});appendFlowStyle(cy,[{selector:'node.selectedReaction',style:{opacity:1}},{selector:'edge.selectedReaction.reactionBackbone',style:{opacity:1,'line-color':'#405a76','source-arrow-color':'#405a76','target-arrow-color':'#405a76'}},{selector:'edge.selectedReaction.reactionSide',style:{opacity:.8}}]).update();}
const selectedReactionRenderBase=flowRender;flowRender=function(){selectedReactionRenderBase();applyReactionSelection()};
applyReactionSelection();

/* Additional medium roots share the existing network without resetting selected paths. */
function addMediumRoots(st,selected){branchInit(st);st.mediumRoots=st.mediumRoots||new Set([st.pool]);let added=0;for(const pool of selected){if(st.mediumRoots.has(pool))continue;const exchanges=st.s.reactions.filter(r=>r.exchange&&r.pool===pool&&r.uptake);if(!exchanges.length)continue;const fid='feed_'+pool,y=Math.max(0,...[...st.keep].map(id=>st.nodes.get(id)?.position?.y||0))+220;st.nodes.set(fid,{data:{id:fid,kind:'feed',pool,label:pool+'\n培地 '+(D.medium?.[pool]??'未指定')+' mmol/L'},position:{x:0,y}});st.keep.add(fid);st.dist.set(fid,0);if(!st.queue.includes(fid))st.queue.push(fid);exchanges.forEach((r,i)=>{const rid=branchEnsure(st,r,1);st.nodes.get(rid).data.direction='取込';st.nodes.get(rid).position={x:180,y:y+i*100};st.keep.add(rid);st.keepEdges.add(branchConnect(st,fid,rid));for(const mid of Object.keys(r.stoich)){const id='m_'+mid;if(!st.keep.has(id))st.nodes.get(id).position={x:360,y:y+i*100};st.keep.add(id);st.keepEdges.add(branchConnect(st,rid,id));}});st.mediumRoots.add(pool);added++;}
// Extend reachability from every root, preserving existing predecessor paths.
const queue=[...st.mediumRoots].map(pool=>pool===st.pool?'feed':'feed_'+pool),seen=new Set(queue);for(let i=0;i<queue.length;i++){const id=queue[i];for(const e of st.out.get(id)||[]){const target=e.data.target;if(!st.dist.has(target)){st.dist.set(target,(st.dist.get(id)||0)+1);st.parent.set(target,{id,edge:e.data.id});st.queue.push(target);if(!st.nodes.get(target).position)st.nodes.get(target).position={x:(st.dist.get(target)||0)*180,y:0};}if(!seen.has(target)){seen.add(target);queue.push(target)}}}return added;}
function installMediumPicker(){if(!flowState||!$('flowPool')||$('addMediumComponents'))return;const b=document.createElement('button');b.id='addMediumComponents';b.textContent='＋ 培地成分をまとめて追加';b.style.cssText='width:100%;margin:8px 0';$('flowPool').parentElement.after(b);const summary=document.createElement('p');summary.id='mediumRootsSummary';b.after(summary);function refresh(){summary.textContent='表示中：'+[...(flowState.mediumRoots||new Set([flowState.pool]))].join('、')}refresh();b.onclick=()=>{const st=flowState,chosen=new Set(),roots=st.mediumRoots||new Set([st.pool]),available=[...new Set(st.s.reactions.filter(r=>r.exchange&&r.uptake&&r.pool).map(r=>r.pool))].sort((a,b)=>Number((D.medium?.[b]||0)>0)-Number((D.medium?.[a]||0)>0)||a.localeCompare(b));const dialog=document.createElement('dialog');dialog.id='mediumPicker';dialog.setAttribute('aria-label','培地成分を追加');dialog.style.cssText='width:min(640px,90vw);max-height:80vh;overflow:auto;border:1px solid #bacbd2;border-radius:12px;padding:20px';dialog.innerHTML='<h2>培地成分を追加</h2><p>表示する起点を追加します。FBAの培地条件は変更しません。未添加の成分は仮想起点です。</p><input id="mediumFilter" aria-label="培地成分を検索" placeholder="成分ID・名称で検索" style="width:100%;min-width:0"><div id="mediumOptions" style="max-height:45vh;overflow:auto;margin:12px 0"></div><button id="confirmMedium" disabled>選択した成分を追加（0）</button> <button id="closeMedium">閉じる</button>';document.body.append(dialog);function list(){const q=$('mediumFilter').value.toLowerCase();$('mediumOptions').innerHTML=available.filter(pool=>{const r=st.s.reactions.find(r=>r.pool===pool),m=st.s.metabolites[Object.keys(r.stoich)[0]];return (pool+' '+(m?.name||'')).toLowerCase().includes(q)}).map(pool=>{const r=st.s.reactions.find(r=>r.pool===pool),m=st.s.metabolites[Object.keys(r.stoich)[0]];return '<label style="display:grid;grid-template-columns:20px minmax(0,1fr);gap:10px;align-items:center;padding:8px;border-bottom:1px solid #eee"><input type="checkbox" data-pool="'+esc(pool)+'" style="min-width:18px;width:18px;height:18px;margin:0;padding:0;justify-self:center;flex:none" '+(roots.has(pool)?'checked disabled':chosen.has(pool)?'checked':'')+'><span style="min-width:0;overflow-wrap:anywhere">'+esc(pool)+' · '+esc(m?.name||'')+'<small style="display:block">'+(roots.has(pool)?'表示中':D.medium?.[pool]>0?D.medium[pool]+' mmol/L':'未添加・仮想起点')+'</small></span></label>'}).join('');$('mediumOptions').querySelectorAll('input').forEach(input=>input.onchange=()=>{if(input.checked)chosen.add(input.dataset.pool);else chosen.delete(input.dataset.pool);$('confirmMedium').disabled=!chosen.size;$('confirmMedium').textContent='選択した成分を追加（'+chosen.size+'）'})}const close=()=>{dialog.close();dialog.remove()};$('closeMedium').onclick=close;dialog.addEventListener('cancel',()=>dialog.remove());$('mediumFilter').oninput=list;$('confirmMedium').onclick=()=>{if(st!==flowState){close();return}addMediumRoots(st,chosen);flowRender();applyReactionSelection();flowCenterRoute();refresh();close()};list();dialog.showModal()};}
const mediumPickerOpenBase=openFlow;openFlow=function(...args){mediumPickerOpenBase(...args);installMediumPicker()};installMediumPicker();
